from pathlib import Path
import json,hashlib,struct
root=Path(__file__).resolve().parents[2];r=root/'docs/independent-eagle/r4';d=json.loads((r/'dense/collision-report.json').read_text());f=d['frames'];assert len(f)==1322 and all(not x['hits'] for x in f) and not d['pageErrors'];assert f[-1]['phase']=='aboard'
base=json.loads((r/'baseline.json').read_text());protected={p:hashlib.sha256((root/p).read_bytes()).hexdigest()==h for p,h in base['protectedSHA256'].items()};assert all(protected.values())
end=next(x for x in f if x['label']=='outbound' and x['ladderTime']==16.2);contacts=end['actualSupportDistancesMeters'];assert max(contacts.values())<=.008
raw=r/'dense/audit';t=json.loads((raw/'topology.json').read_text());b=(raw/end['file']).read_bytes();v=struct.unpack('<'+'f'*(len(b)//4),b);bounds=[];start=0
for item in t['entries'][:2]:
 p=v[start*3:(start+item['vertices'])*3];bounds.append([[min(p[i::3]),max(p[i::3])] for i in range(3)]);start+=item['vertices']
assert all(q[0][0]>=-.55 and q[0][1]<=.55 and q[2][0]>=1.275 and q[2][1]<=2.145 for q in bounds)
minZ=min(v[2::3]);assert minZ>1.601
motion=json.loads((r/'motion-continuity.json').read_text());assert motion['pass']
rig=json.loads((r/'rig-preservation.json').read_text());assert rig['r3']['vertexPositionsSHA256']==rig['r4']['vertexPositionsSHA256'];assert rig['r3']['restJoints']==rig['r4']['restJoints'] and rig['r4']['weightError']<1e-6
smoke=json.loads((r/'production-smoke.json').read_text());assert not smoke['errors'] and smoke['out']['phase']=='porch' and smoke['back']['phase']=='aboard' and smoke['back']['hatchOpen']==0 and smoke['default']=={'phase':'flight','r4':False}
result={'gate':'PASS: isolated kinematic hatch/porch out and return','protectedHashesUnchanged':protected,'geometrySamples':len(f),'meshSampleHz':1/d['sampleStepSeconds'],'simulationHz':1/d['simulationStepSeconds'],'actionDurationSecondsEachWay':21.6,'intersectionFrames':0,'motionContinuity':motion,'platformContactsMeters':contacts,'maxNearestGroundedBootDistanceMeters':max(min(x['actualSupportDistancesMeters']['bootR'],x['actualSupportDistancesMeters']['bootL']) for x in f),'platformBootBounds':bounds,'wholeActorMinZOnPorch':minZ,'thresholdForwardZ':1.601,'maxLegReachMeters':max(c['reach'] for x in f for c in x['contacts']),'twoLegSegmentLengthMeters':.74,'maxHandIKErrorMeters':max(c['reachError'] for x in f for c in x['handContacts']),'scanVertexPositionsSHA256':rig['r4']['vertexPositionsSHA256'],'scale':[1,1,1],'environment':{'macOS':'26.6.2','blender':'5.1.1','python':'3.9.6','node':rig['node'],'chrome':rig['chrome']},'productionAndDefaultUI':'PASS','scopeLimitations':['30 Hz sampled geometry check, not a mathematical continuous-collision guarantee','Kinematic guided passage, not force/pressure-suit biomechanics certification','No new ladder rhythm, rover, dust, instrument or mobile performance work','R2 historical and aft-structure approximations remain']}
